import { describe, expect, it } from "vitest";
import type { IdeaRecord } from "../idea/index.js";
import { exclusionOf, type FrontierIssue } from "./exclusion.js";

const ticket = (overrides: Partial<FrontierIssue> = {}): FrontierIssue => ({
  number: 20,
  title: "Make the tick print its queue",
  body: "Make the tick print its queue.",
  labels: ["ready-for-agent"],
  assignees: 0,
  openBlockers: 0,
  subIssues: 0,
  createdAt: "2026-01-01T00:00:00Z",
  ...overrides,
});

const IDEA_BODY =
  "<!-- Generated by `harness idea sync` from docs/ideas/0001-x.md. Edit that file; changes made here are overwritten. -->\n\n## Summary\n\nx\n";

const idea = (outcome?: string): IdeaRecord => ({
  number: "0001",
  slug: "x",
  path: "docs/ideas/0001-x.md",
  title: "X",
  summary: "s",
  hypothesis: "h",
  expectedOutcome: "e",
  measurement: "m",
  safetyPattern: "feature-flagged",
  date: "2026-01-01",
  issue: "20",
  ...(outcome === undefined ? {} : { outcome }),
});

describe("exclusionOf", () => {
  it("keeps an open ready-for-agent ticket that has no blocker, parent, assignee or paused or spec label", () => {
    expect(exclusionOf(ticket(), undefined)).toBeUndefined();
  });

  it("excludes an issue without the ready-for-agent label, so nothing unapproved is queued", () => {
    expect(exclusionOf(ticket({ labels: ["horizon:next"] }), undefined)).toBe(
      "not-ready",
    );
  });

  it("excludes an assigned issue", () => {
    expect(exclusionOf(ticket({ assignees: 1 }), undefined)).toBe("assigned");
  });

  it("excludes a paused issue even when it is labelled ready-for-agent", () => {
    expect(
      exclusionOf(ticket({ labels: ["ready-for-agent", "paused"] }), undefined),
    ).toBe("paused");
  });

  it("excludes a spec issue", () => {
    expect(
      exclusionOf(ticket({ labels: ["ready-for-agent", "spec"] }), undefined),
    ).toBe("spec");
  });

  it("excludes an issue with an open blocker", () => {
    expect(exclusionOf(ticket({ openBlockers: 1 }), undefined)).toBe("blocked");
  });

  it("excludes a parent issue with sub-issues, which is not a ticket", () => {
    expect(exclusionOf(ticket({ subIssues: 3 }), undefined)).toBe("sub-issue");
  });

  it("excludes a grilling source, whose body starts with Filed by", () => {
    expect(
      exclusionOf(
        ticket({ body: "Filed by the grilling session on 2026-11-20." }),
        undefined,
      ),
    ).toBe("grilling-source");
  });

  it("keeps an idea issue while its idea record has no outcome", () => {
    expect(exclusionOf(ticket({ body: IDEA_BODY }), idea())).toBeUndefined();
  });

  it("excludes an idea issue whose idea record already has an outcome", () => {
    expect(exclusionOf(ticket({ body: IDEA_BODY }), idea("success"))).toBe(
      "idea-outcome",
    );
  });

  it("excludes an idea issue that has no idea record, rather than queuing it as a plain ticket", () => {
    expect(exclusionOf(ticket({ body: IDEA_BODY }), undefined)).toBe(
      "idea-missing",
    );
  });

  it("reports the first reason that applies, in the rule's order", () => {
    expect(
      exclusionOf(
        ticket({ assignees: 1, openBlockers: 2, subIssues: 1 }),
        undefined,
      ),
    ).toBe("assigned");
  });
});
